import os,stat,sys,json,hashlib,base64,bz2,types,signal
from pathlib import Path
signal.alarm(55)
pins={'cleanup_root01.py': {'bytes': 9616, 'sha256': 'f5af7be27641e0ba6dbc6bd5975240c1a33bbb1b8fb56c53b0c7be3791687a3e'}, 'cleanup_remoteocd01.py': {'bytes': 7723, 'sha256': '4c6e8bbfecb10a42d9963a0159a3f3e869bbf9db5e9b13b4f09a099991f39059'}, 'static_remote.py': {'bytes': 33321, 'sha256': '8ba9b190c38e728013a383348c60c287b0366607f65f703161cf7f2e142d36f8'}}
packet=json.loads(bz2.decompress(base64.b64decode('')).decode())

for name,pin in pins.items():
 raw=packet[name].encode();assert len(raw)==pin['bytes'] and hashlib.sha256(raw).hexdigest()==pin['sha256']
h=types.ModuleType('fixed_stage_helper');exec(compile(packet['static_remote.py'],'/__sumox__/helper.py','exec'),h.__dict__)
r=types.ModuleType('fixed_stage_recipe');exec(compile(packet['cleanup_remoteocd01.py'],'/__sumox__/recipe.py','exec'),r.__dict__)
root=os.open('/',os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW|os.O_CLOEXEC)
stage='/home/arduino/sumox26_codex_build/cleanup-recorder-next-root01'
try:
 identity=h.identity(root);assert identity==r.EXPECTED
 for name,pin in r.PINS.items():r.checked_bytes(h.logical_read(root,pin[2],pin[0]),pin)
 with h.directory(root,'/tmp/remoteocd') as fd:
  info=os.fstat(fd);assert info.st_dev==34 and info.st_ino==2281 and info.st_uid==info.st_gid==1000
  scratch=r.inventory(h,fd,r.PINS)
 with h.directory(root,'/home/arduino/sumox26_codex_build') as parent:
  parent_identity=r.stamp(os.fstat(parent))
  try: os.stat('cleanup-recorder-next-root01',dir_fd=parent,follow_symlinks=False)
  except FileNotFoundError: absent=True
  else: raise ValueError('Fresh cleanup owner already exists')
  assert r.stamp(os.fstat(parent))==parent_identity
 for name,pin in r.PINS.items():r.checked_bytes(h.logical_read(root,pin[2],pin[0]),pin)
 assert h.identity(root)==identity
 print(json.dumps({'status':'ABSENT_OWNER_READONLY_CHECKED','identity':identity,'stage':stage,'owner_absent':absent,'parent_identity':parent_identity,'files':pins,'scratch_before':scratch,'originals_unchanged':True},sort_keys=True))
finally:os.close(root)
